import type { Player, Position, Squad } from './types';

// ---------------------------------------------------------------------------
// WORLD CUP SQUAD DATASET.
//
// 1986, 1990 and 1994 (24 nations, 22-man squads), 1998 and 2002 (both 32 nations): full
// researched datasets. Names, shirt numbers and the goalkeeper/defender/midfielder/forward
// split are verified against the Wikipedia "<year> FIFA World Cup squads" lists. For 1986
// the twelve SPECIFIC positions are additionally reconciled against the RSSSF match
// line-ups, which print each side by line (keeper - defence - midfield - attack), so a
// player carries the role he actually filled in Mexico; ratings are a BLEND of each
// player's ability entering the tournament and how he actually performed there (standouts
// up, players caught in heavy defeats nudged down, bench/unused players left at their
// baseline).
// Historical nations keep their period identity: the 1990 champions (West Germany) are
// recorded as Germany on the GER code;
// the Soviet Union (URS), Czechoslovakia (TCH) and Yugoslavia (YUG) are their own codes,
// with players who continued for a successor nation (e.g. Prosinecki YUG -> Croatia,
// Gorlukovich URS -> Russia) sharing one identity across both.
//
// 2022 (Qatar): full researched dataset - all 32 nations, each with its
// official 26-man squad (Iran registered 25), shirt numbers and positions
// verified against the FIFA / Wikipedia tournament squad lists. Elo ratings
// are a holistic judgement of each player's STRENGTH AT THE TIME of the
// tournament (Nov/Dec 2022, NOT current), cross-checked and debated across
// several research passes. Scale: 60 (weakest) .. 99 (best); duplicates are
// expected and fine.
//
// Each squad is a single nation at a single tournament. Players are tagged with
// one or more specific positions (a slot only accepts a matching position).
// Central midfielders carry their real role(s): DM (holding), CM (central),
// AM (attacking) - often a combo such as DM/CM or AM/CM.
//
// `personId` is derived from the name, so the same human appearing in multiple
// squads (e.g. Messi in Argentina 2006 and 2022) shares one identity and can
// only be drafted once. Keep name spellings identical across squads for that to
// work; distinct people MUST have distinct names (e.g. Amadou Onana vs Andre
// Onana, Marcus Thuram vs Thuram/Lilian) or they would collide into one person.
// Two different people who must *display* the same name (the flag beside it tells
// them apart) instead pass an explicit personId override as the 5th Row element -
// see the two "Luis Marín" (Costa Rica CB vs Chile GK).
// ---------------------------------------------------------------------------

function slug(name: string): string {
    // Strip combining diacritics (NFD splits 'í' into 'i' + accent, U+0300..U+036F).
    return name
        .toLowerCase()
        .normalize('NFD')
        .replace(/[̀-ͯ]/g, '')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '');
}

// [number, name, positions, rating] plus an optional personId override for a
// same-name namesake that must display identically (see the header note).
type Row = [number, string, Position[], number, string?];

function squad(code: string, nation: string, year: number, rows: Row[]): Squad {
    const id = `${code.toLowerCase()}-${year}`;
    const players: Player[] = rows.map(([number, name, positions, elo, personId]) => ({
        id: `${id}-${number}`,
        personId: personId ?? slug(name),
        squadId: id,
        number,
        name,
        positions,
        elo,
    }));
    return { id, code, nation, year, players };
}

