    // ===== 1982 FIFA World Cup (Spain) - full 24-nation researched dataset. 22-man
    // squads, except EL SALVADOR, who brought only 20 and never filled the roster
    // (Wikipedia and planetworldcup agree), so the block is 526 rows and not 528.
    // Sourced exactly as 1986 was: the Wikipedia "1982 FIFA World Cup squads" list for
    // names, shirt numbers and the GK/DF/MF/FW split, each player's own infobox for the
    // twelve SPECIFIC positions, and the RSSSF match line-ups (which print a side as
    // keeper - defence - midfield - attack) for the role he actually filled in Spain;
    // a man who never got on the pitch carries the role he was picked for. Ratings
    // blend pre-tournament standing with the Spain 82 showing: Rossi's Golden Boot out
    // of three anonymous group games, Zico and Socrates on the best side never to win
    // it, Rummenigge playing the knockouts on a thigh injury, Algeria beating West
    // Germany, El Salvador conceding ten. West Germany is recorded as Germany on GER
    // and the Soviet Union, Czechoslovakia and Yugoslavia keep URS / TCH / YUG, exactly
    // as 1986 and 1990 do. =====
